  private def createFloor(cols: Int, rows: Int, spriteMap: EvaSpriteMap, tiles: List[Int]): Matrix[FloorSprite] = {
    Matrix(cols, rows, pim => spriteMap.sprites.find(_.id == tiles(pim.asIndex.get)).get.asInstanceOf[FloorSprite])
  }

  def createSmallExample(spriteMap: EvaSpriteMap): Matrix[FloorSprite] = {

    //spriteMap.sprites.sortBy(_.id).foreach(sprite => println("sprite " + sprite.id + ": " + sprite.file))
    val tileIds: List[Int] = List(0, 1, 1, 1, 2, 16, 3, 88, 5, 18, 32, 34, 98, 32, 34)
    val validTiles = spriteMap.tiles.map(_.id)

    tileIds.filterNot(validTiles contains _).foreach(asdf => println("[ERROR] Tile " + asdf + " does not exist!"))

    createFloor(5, 3, spriteMap, tileIds)
  }

  def createEmptyExample(spriteMap: EvaSpriteMap, dimension: MatrixDimension): Matrix[FloorSprite] = {
    Matrix(dimension.cols, dimension.rows, pos => spriteMap.defaultEmpty)
  }


  def main(args: Array[String]): Unit = {
    val context: ExecutionContextExecutor = scala.concurrent.ExecutionContext.global

    ScenarioCache.localInstance.loadScenario("topdown48f:AQMAAQwDAAEIAwABYAEBYIU=:AA==")

    val cache = new ScenarioCache(LocalResourceReader)
    val spriteMapF = cache.loadSpriteMap(SpriteMapResourceIdentifier.getFrom("topdown", 8).get)
    spriteMapF.onComplete(sm => {
      val floorMap = createEmptyExample(sm.get, MatrixDimension(12,8))
      val str = FloorMapIO(sm.get).encode(EvaFloorMap(floorMap, Set[Person]()))
      println("Result:\n" + str)
    })(using context)

    Thread.sleep(5000)
    println("---")

  }








}
